// Hiza Hiza: single-file app. Unpacks its own files to a temp folder and starts the server.
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { tmpdir } from 'node:os';
import { spawn } from 'node:child_process';
const FILES = {"server/store.mjs": "", "server/pdf.mjs": "", "server/payments.mjs": "", "server/folio.mjs": "", "server/mailer.mjs": "", "server/server.mjs": "", "pms/pms.mjs": "", "pms/channel.mjs": "", "pms/node.mjs": "", "pms/ical.mjs": "", "web/stay.html": "", "web/styles.css": "", "web/index.html": "", "web/host.html": "", "web/host.css": "", "web/intro.css": "", "web/photos/living-room.jpg": "", "web/photos/kitchen.jpg": "", "web/photos/bedroom-2.jpg": "", "web/photos/bedroom-2-full.jpg": "", "web/photos/living-loft.jpg": "", "web/photos/pdf-cover.jpg": "", "web/photos/living-loft-full.jpg": "", "web/photos/bedroom-1.jpg": "", "web/photos/bedroom-1-full.jpg": "", "web/photos/living-room-full.jpg": "", "web/photos/README.txt": "", "web/photos/kitchen-full.jpg": "", "web/photos/exterior.jpg": "", "web/js/mrz.js": "", "web/js/calendar.js": "", "web/js/lang-hr.js": "", "web/js/i18n.js": "", "web/js/lang-sl.js": "", "web/js/lang-switch.js": "", "web/js/daylight.js": "", "web/js/area-data.js": "", "web/js/loader-logo.js": "", "web/js/placeholders.js": "", "web/js/selection.js": "", "web/js/sui-wallet.js": "", "web/js/dom.js": "", "web/js/forest.js": "", "web/js/folio-view.js": "", "web/js/lang-de.js": "", "web/js/gallery.js": "", "web/js/scan.js": "", "web/js/checkout.js": "", "web/js/intro.js": "", "web/js/garden.js": "", "web/js/lang-it.js": "", "web/js/spaces.js": "", "web/js/citytax.js": "", "web/js/area.js": "", "web/js/sound.js": "", "web/js/main.js": "", "web/js/mock-data.js": "", "web/js/dates.js": "", "web/js/host.js": "", "web/js/policy.js": "", "web/js/quote.js": "", "web/js/config.js": "", "web/js/gallery-house.js": "", "web/js/title-branch.js": "", "web/js/photo-overlay.js": "", "web/js/host-rates.js": "", "web/escrow.html": "", "web/js/escrow-page.js": "", "web/market.html": "", "web/js/market-page.js": "", "web/js/resale.js": "", "web/js/escrow-sell.js": "", "server/suisig.mjs": "", "web/js/wallet-links.js": "", "web/terms.html": "", "web/js/terms-page.js": "", "web/js/terms-text.js": "", "web/js/terms-values.js": "", "web/crypto.html": "", "web/js/crypto-page.js": "", "web/js/crypto-text.js": "", "web/doc.css": "", "web/js/doc-parts.js": "", "web/js/explorer.js": "", "web/js/host-link.js": "", "web/js/host-payments.js": "", "web/manifest.webmanifest": "", "web/sw.js": "", "web/js/pwa.js": "Ly8gUmVnaXN0ZXJzIHRoZSB0aW55IHNlcnZpY2Ugd29ya2VyIHNvIHBob25lcyBvZmZlciAiSW5zdGFsbCBhcHAiIGZvciB0aGUgc2l0ZS4KaWYgKCdzZXJ2aWNlV29ya2VyJyBpbiBuYXZpZ2F0b3IpIGFkZEV2ZW50TGlzdGVuZXIoJ2xvYWQnLCAoKSA9PiBuYXZpZ2F0b3Iuc2VydmljZVdvcmtlci5yZWdpc3RlcignL3N3LmpzJykuY2F0Y2goKCkgPT4ge30pKTsK", "web/icons/icon-192.png": "", "web/icons/icon-512.png": "", "web/icons/icon-maskable-512.png": ""};
const root = join(tmpdir(), 'hiza-app');
for (const [p, b64] of Object.entries(FILES)) { const f = join(root, p); mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, Buffer.from(b64, 'base64')); }
const child = spawn(process.execPath, [join(root, 'server/server.mjs')], { stdio: 'inherit', env: { ...process.env, DATA_FILE: process.env.DATA_FILE || join(tmpdir(), 'pms.json') } });
child.on('exit', (code) => process.exit(code ?? 1));
for (const s of ['SIGTERM', 'SIGINT']) process.on(s, () => child.kill(s));
